INSERT INTO `policies` (`id`, `title`, `slug`, `content`, `created_at`, `updated_at`) VALUES
(4, 'Refund policy', 'refund-policy', '<h1 dir=\"ltr\" data-pm-slice=\"0 0 []\"><br>Return and Refund Policy</h1><h2 dir=\"ltr\">Returns</h2><p dir=\"ltr\">You may request a return within 7 days of receiving your order if:</p><ul class=\"tight\" data-tight=\"true\" dir=\"ltr\"><li><p dir=\"ltr\">The product is damaged, defective, or incorrect.</p></li><li><p dir=\"ltr\">The item remains unused, unopened, and in its original packaging.</p></li></ul><p dir=\"ltr\">To initiate a return, please reach out to us via WhatsApp or email, providing your order number, photos of the product, and a brief description of the issue.</p><p dir=\"ltr\"><strong>Please note:</strong><br>Returns will not be accepted in the following situations:</p><ul class=\"tight\" data-tight=\"true\" dir=\"ltr\"><li><p dir=\"ltr\">Change of mind or personal preference.</p></li><li><p dir=\"ltr\">Items that are used, opened, or washed.</p></li><li><p dir=\"ltr\">Products purchased during sales or promotional offers (unless faulty).</p></li></ul><h2 dir=\"ltr\">Refunds</h2><p dir=\"ltr\">Upon receiving and inspecting your returned item, we will inform you of the approval or rejection of your refund request.</p><p dir=\"ltr\">If approved:</p><ul class=\"tight\" data-tight=\"true\" dir=\"ltr\"><li><p dir=\"ltr\">The refund will be processed within 7 working days through bank transfer, mobile wallet, or cash payment options.</p></li><li><p dir=\"ltr\">Shipping costs are non-refundable, except in cases of incorrect or damaged deliveries.</p></li><li><p dir=\"ltr\">For cash-on-delivery orders, refunds will be issued after deducting applicable delivery fees.</p></li></ul><h2 dir=\"ltr\">Exchanges</h2><p dir=\"ltr\">We offer replacements only for items that are defective or damaged. Exchange requests must be submitted within 3 days of delivery, subject to product availability.</p><h2 dir=\"ltr\">Contact Information</h2><p dir=\"ltr\">For any inquiries regarding returns or refunds, feel free to get in touch with us:</p><ul class=\"tight\" data-tight=\"true\" dir=\"ltr\"><li><p dir=\"ltr\"><strong>Phone/WhatsApp:</strong> +923273546753</p></li><li><p dir=\"ltr\"><strong>Email:</strong> tahashehzad063@gmail.com<br><img src=\"data:image/jpeg;base64,\" data-filename=\"398a8361-b542-4526-98fc-0b8674390e48.jpg\" style=\"width: 720px;\"><br></p></li></ul>', '2025-08-05 02:43:33', '2025-08-05 03:17:24');
INSERT INTO `policies` (`id`, `title`, `slug`, `content`, `created_at`, `updated_at`) VALUES
(5, 'Shipping Policy', 'shipping-policy', '<h1 dir=\"ltr\" data-pm-slice=\"0 0 []\">Shipping Policy</h1><p dir=\"ltr\">We are committed to delivering your order quickly and securely. Please review our shipping policy below to understand how we process and deliver your items.</p><h2 dir=\"ltr\">1. Order Processing Time</h2><p dir=\"ltr\">All orders are processed within 1–2 business days following payment confirmation. Orders placed on weekends or public holidays will be processed on the next business day.</p><h2 dir=\"ltr\">2. Delivery Time</h2><ul class=\"tight\" data-tight=\"true\" dir=\"ltr\"><li><p dir=\"ltr\"><strong>Standard Delivery</strong>: 5–7 business days across Pakistan.</p></li><li><p dir=\"ltr\"><strong>Remote or Rural Areas</strong>: Additional time may be required for delivery to remote locations.</p></li><li><p dir=\"ltr\"><strong>Note</strong>: Delivery timelines may vary due to courier delays, weather conditions, or other unforeseen circumstances.</p></li></ul><h2 dir=\"ltr\">3. Shipping Charges</h2><p dir=\"ltr\">Shipping costs are calculated at checkout based on your location and the weight of your order. In some cases, advance payment for delivery charges may be required. Once paid, kindly send a screenshot of the payment confirmation via WhatsApp to +92 273546753 to expedite order processing.</p><h2 dir=\"ltr\">4. Shipping Methods</h2><p dir=\"ltr\">We collaborate with trusted courier services to ensure safe and timely delivery, including:</p><ul class=\"tight\" data-tight=\"true\" dir=\"ltr\"><li><p dir=\"ltr\">TCS</p></li><li><p dir=\"ltr\">M&amp;P</p></li><li><p dir=\"ltr\">Leopard Courier</p></li><li><p dir=\"ltr\">Pakistan Post (in select cases)</p></li></ul><h2 dir=\"ltr\">5. Cash on Delivery (COD)</h2><p dir=\"ltr\">Cash on Delivery is available for most products across Pakistan. Please ensure the provided phone number is accurate and reachable, as the courier may contact you prior to delivery.</p><h2 dir=\"ltr\">6. Delays or Issues</h2><p dir=\"ltr\">If your order is delayed beyond the estimated timeframe, please reach out to us immediately. While we are not responsible for delays caused by courier services, we will work diligently to assist with tracking and resolving any issues.</p><h2 dir=\"ltr\">7. Undelivered Orders</h2><p dir=\"ltr\">If an order is returned due to an incorrect address or failure to receive the delivery, we will contact you to arrange reshipment. Additional shipping charges may apply.</p><h2 dir=\"ltr\">8. Contact Us</h2><p dir=\"ltr\">For any shipping-related inquiries or to share proof of delivery payment, please reach out to us at:</p><ul class=\"tight\" data-tight=\"true\" dir=\"ltr\"><li><p dir=\"ltr\">Phone: +92 327 354 6753</p></li><li><p dir=\"ltr\">Email: tahashehzad063@gmail.com</p></li></ul><p dir=\"ltr\">Thank you for choosing us! We’re here to ensure a seamless shopping experience.<br><br><img src=\"data:image/jpeg;base64,\" data-filename=\"shipping-policy-we-are-committed-to-delivering-yo.jpeg\" style=\"width: 1023.99px;\"><br></p>', '2025-08-05 02:53:54', '2025-08-05 03:33:48');
INSERT INTO `policies` (`id`, `title`, `slug`, `content`, `created_at`, `updated_at`) VALUES
(6, 'Privacy policy', 'privacy-policy', '<h1 dir=\"ltr\" data-pm-slice=\"0 0 []\">Privacy Policy</h1><p dir=\"ltr\">We are dedicated to valuing your privacy and ensuring the protection of your personal information. This Privacy Policy explains how we collect, use, and safeguard your data when you visit or make a purchase on our website.</p><h2 dir=\"ltr\">1. Information We Collect</h2><p dir=\"ltr\">When you visit or shop with us, we may collect the following:</p><ul class=\"tight\" data-tight=\"true\" dir=\"ltr\"><li><p dir=\"ltr\"><strong>Personal Details</strong>: Name, phone number, email address, and shipping address.</p></li><li><p dir=\"ltr\"><strong>Order Information</strong>: Product selections, payment details (excluding full credit card numbers), and delivery details.</p></li><li><p dir=\"ltr\"><strong>Device Information</strong>: IP address, browser type, and cookies to enhance your experience.</p></li></ul><h2 dir=\"ltr\">2. How We Use Your Information</h2><p dir=\"ltr\">We utilize your data to:</p><ul class=\"tight\" data-tight=\"true\" dir=\"ltr\"><li><p dir=\"ltr\">Process and fulfill your orders efficiently.</p></li><li><p dir=\"ltr\">Contact you regarding your purchases or to assist with customer service inquiries.</p></li><li><p dir=\"ltr\">Send updates about new products, offers, or promotions (only with your consent).</p></li><li><p dir=\"ltr\">Improve our website’s performance and user experience.</p></li></ul><h2 dir=\"ltr\">3. Protection of Your Data</h2><p dir=\"ltr\">We implement robust measures to safeguard your personal information against unauthorized access, loss, or misuse. All sensitive data is encrypted and stored securely.</p><h2 dir=\"ltr\">4. Sharing of Information</h2><p dir=\"ltr\">We do not sell, trade, or rent your personal information to third parties. Your data may be shared with trusted service providers (e.g., courier companies or payment processors) solely to fulfill your order.</p><h2 dir=\"ltr\">5. Cookies</h2><p dir=\"ltr\">We use cookies to enhance your browsing experience, remember your preferences, and analyze website performance. You can disable cookies via your browser settings if desired.</p><h2 dir=\"ltr\">6. Your Rights</h2><p dir=\"ltr\">You are entitled to:</p><ul class=\"tight\" data-tight=\"true\" dir=\"ltr\"><li><p dir=\"ltr\">Request access to your personal data.</p></li><li><p dir=\"ltr\">Request corrections or deletion of your information.</p></li><li><p dir=\"ltr\">Opt out of marketing communications at any time.</p></li></ul><h2 dir=\"ltr\">7. Changes to This Policy</h2><p dir=\"ltr\">We may update this policy as needed. Any changes will be reflected on this page with an updated \"Last Updated\" date.</p><h2 dir=\"ltr\">8. Contact Us</h2><p dir=\"ltr\">For any questions or concerns about this Privacy Policy, please reach out to us:</p><ul class=\"tight\" data-tight=\"true\" dir=\"ltr\"><li><p dir=\"ltr\">Phone/WhatsApp: +92 327 354 6753</p></li><li><p dir=\"ltr\">Email: tahashehzad063@gmail.com</p></li></ul><p dir=\"ltr\">Thank you for trusting us with your information. We are committed to maintaining your privacy.<br><img src=\"data:image/jpeg;base64,\" data-filename=\"privacy-policy-we-are-dedicated-to-valuing-your-p.jpeg\" style=\"width: 1028.89px;\"><br></p>', '2025-08-05 03:22:54', '2025-08-05 03:26:43');
INSERT INTO `policies` (`id`, `title`, `slug`, `content`, `created_at`, `updated_at`) VALUES
(7, 'Terms and condition', 'terms-and-condition', '<h1 dir=\"ltr\" data-pm-slice=\"0 0 []\">Terms of Service</h1><p dir=\"ltr\">Welcome! By accessing or using our website, you agree to comply with and be bound by the following terms and conditions. Please take a moment to review them carefully before engaging with our services.</p><h2 dir=\"ltr\">1. General</h2><p dir=\"ltr\">By visiting our site or making a purchase, you engage in our “Service” and agree to be bound by these Terms of Service. These terms apply to all users, including browsers, customers, and vendors.</p><h2 dir=\"ltr\">2. Products and Pricing</h2><p dir=\"ltr\">All products listed on our site are subject to availability. We reserve the right to adjust product prices, details, or availability at any time without prior notice. We strive to ensure accuracy in product descriptions and pricing, but we cannot guarantee that all content is free of errors.</p><h2 dir=\"ltr\">3. Orders and Payments</h2><p dir=\"ltr\">Upon placing an order, you will receive a confirmation. We reserve the right to cancel any order due to product unavailability, errors in product details or pricing, or suspected fraudulent activity. Payments can be made via Cash on Delivery, Easypaisa, JazzCash, or bank transfer, as offered on the site.</p><h2 dir=\"ltr\">4. Shipping and Delivery</h2><p dir=\"ltr\">Delivery times may vary based on your location and potential courier delays. We aim to process orders promptly, but we are not responsible for delays caused by third-party courier services.</p><h2 dir=\"ltr\">5. Returns and Refunds</h2><p dir=\"ltr\">Our return and refund policy is detailed separately. Please refer to our Return &amp; Refund Policy for complete information.</p><h2 dir=\"ltr\">6. User Responsibilities</h2><p dir=\"ltr\">You agree not to:</p><ul class=\"tight\" data-tight=\"true\" dir=\"ltr\"><li><p dir=\"ltr\">Use our products for any illegal or unauthorized purpose.</p></li><li><p dir=\"ltr\">Transmit worms, viruses, or destructive code.</p></li><li><p dir=\"ltr\">Attempt unauthorized access to our systems or interfere with site security or functionality.</p></li></ul><h2 dir=\"ltr\">7. Intellectual Property</h2><p dir=\"ltr\">All content on this site, including text, images, logos, graphics, and design, is our property and protected by applicable copyright and trademark laws. Unauthorized use of our content is strictly prohibited.</p><h2 dir=\"ltr\">8. Third-Party Links</h2><p dir=\"ltr\">Our website may include links to third-party sites. We are not responsible for their content or accuracy and do not endorse them.</p><h2 dir=\"ltr\">9. Limitation of Liability</h2><p dir=\"ltr\">We are not liable for any direct, indirect, incidental, or consequential damages arising from your use of our site or services. All products are used at your own risk.</p><h2 dir=\"ltr\">10. Changes to Terms</h2><p dir=\"ltr\">We may modify these Terms of Service at any time. Updates will be posted on this page, and your continued use of the website signifies your acceptance of the revised terms.</p><h2 dir=\"ltr\">11. Contact Information</h2><p dir=\"ltr\">For questions about these Terms of Service, please contact us:</p><ul class=\"tight\" data-tight=\"true\" dir=\"ltr\"><li><p dir=\"ltr\">Phone/WhatsApp: +92 327 354 6753</p></li><li><p dir=\"ltr\">Email: tahashehzad063@gmail.com</p></li></ul><p dir=\"ltr\">Thank you for choosing our services. We’re here to assist you!<br><img src=\"data:image/jpeg;base64,\" data-filename=\"terms-of-service-welcome--by-accessing-or-using-o.jpeg\" style=\"width: 1023.99px;\"><br></p>', '2025-08-05 03:23:27', '2025-08-05 03:43:00');
INSERT INTO `policies` (`id`, `title`, `slug`, `content`, `created_at`, `updated_at`) VALUES
(8, 'Cancellations', 'cancellations', '<h1 dir=\"ltr\" data-pm-slice=\"0 0 []\">Purchase and Cancellation Guidelines</h1><p dir=\"ltr\">We are committed to ensuring a smooth and transparent shopping experience. Please review the following details regarding purchase methods and order cancellations.</p><h2 dir=\"ltr\">Purchase Options</h2><p dir=\"ltr\">We offer the following payment and purchase methods:</p><ul class=\"tight\" data-tight=\"true\" dir=\"ltr\"><li><p dir=\"ltr\"><strong>Cash on Delivery (COD)</strong>: Available for most locations across Pakistan.</p></li><li><p dir=\"ltr\"><strong>Advance Payment (Optional)</strong>: Through Easypaisa, JazzCash, or bank transfer. Payment details will be provided upon request. In some instances, advance delivery charges may be required before order processing. Kindly send a screenshot of the payment via WhatsApp to +92 308 0603 740.</p></li></ul><h2 dir=\"ltr\">Order Confirmation</h2><p dir=\"ltr\">Orders placed via our website or WhatsApp will be confirmed by our team prior to dispatch. You will receive an order confirmation via WhatsApp or SMS. Unconfirmed orders may be automatically cancelled.</p><h2 dir=\"ltr\">Order Cancellation Policy</h2><p dir=\"ltr\">You may cancel your order under the following conditions:</p><ul class=\"tight\" data-tight=\"true\" dir=\"ltr\"><li><p dir=\"ltr\"><strong>Before Dispatch</strong>: You can cancel your order within 12 hours of placement or before dispatch by contacting us on WhatsApp.</p></li><li><p dir=\"ltr\"><strong>After Dispatch</strong>: Once the order is shipped, cancellation is not possible. Please refer to our Return &amp; Refund Policy for cases involving damaged, defective, or incorrect products.</p></li><li><p dir=\"ltr\"><strong>Non-Responsive Orders</strong>: Orders with incomplete or unverified contact details may be cancelled without prior notice.</p></li></ul><h2 dir=\"ltr\">How to Cancel an Order</h2><p dir=\"ltr\">To cancel your order, please reach out to us via:</p><ul class=\"tight\" data-tight=\"true\" dir=\"ltr\"><li><p dir=\"ltr\">Phone/WhatsApp: +92 327 354 6753</p></li><li><p dir=\"ltr\">WhatsApp: +92 308 0603 740</p></li></ul><p dir=\"ltr\">We value your trust and are here to assist you throughout the process!<br><img src=\"data:image/jpeg;base64,\" data-filename=\"purchase-and-cancellation-guidelines--we-are-comm.jpeg\" style=\"width: 1028.89px;\"><br></p>', '2025-08-05 03:28:22', '2025-08-05 03:28:22');
INSERT INTO `policies` (`id`, `title`, `slug`, `content`, `created_at`, `updated_at`) VALUES
(9, 'Contacts', 'contacts', '<p dir=\"auto\" style=\"white-space-collapse: preserve;\">We’re delighted to assist you! For any questions regarding our products, orders, or services, please feel free to reach out to us through the following channels:</p><ul dir=\"auto\">\r\n<li>Phone/WhatsApp: +92 327 354 6753</li>\r\n<li>WhatsApp: +92 3273546753</li>\r\n<li>Email: <a href=\"mailto:tahashehzad063@gmail.com\" target=\"_blank\" rel=\"noopener noreferrer nofollow\">tahashehzad063@gmail.com</a></li>\r\n</ul><p>\r\n\r\n</p><p dir=\"auto\" style=\"white-space-collapse: preserve;\">We look forward to helping you!\r\n<img src=\"data:image/jpeg;base64,\" data-filename=\"we-re-delighted-to-assist-you--for-any-questions-.jpeg\" style=\"width: 1023.99px;\">\r\n</p>', '2025-08-05 03:31:45', '2025-08-05 03:40:04');
INSERT INTO `policies` (`id`, `title`, `slug`, `content`, `created_at`, `updated_at`) VALUES
(10, 'Faqs', 'faqs', '<p><br></p><div class=\"accordion mb-3\" id=\"accordion_1754886109052\">\r\n                            <div class=\"accordion-item\">\r\n                                <h2 class=\"accordion-header\">\r\n                                    <button class=\"accordion-button\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapse_1754886109052\" aria-expanded=\"true\">What types of products can I find at Roshni Store?</button>\r\n                                </h2>\r\n                                <div id=\"collapse_1754886109052\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#accordion_1754886109052\" style=\"\">\r\n                                    <div class=\"accordion-body\">\r\n                                        <p>Roshni Store offers a wide variety of products, including women’s fashion, beauty items, handbags, kids’ accessories, and trending tech gadgets. We carefully select each item to ensure high quality, stylish designs, and affordability. Our goal is to provide something special for every customer’s lifestyle and needs.</p><p><br></p></div></div></div></div><div class=\"accordion mb-3\" id=\"accordion_1754886140194\">\r\n                            <div class=\"accordion-item\">\r\n                                <h2 class=\"accordion-header\">\r\n                                    <button class=\"accordion-button\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapse_1754886140194\" aria-expanded=\"true\">Do you deliver products all over Pakistan, including remote areas?</button></h2>\r\n                            </div>\r\n                        </div><div class=\"accordion mb-3\" id=\"accordion_1754886109052\"><div class=\"accordion-item\"><div id=\"collapse_1754886109052\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#accordion_1754886109052\" style=\"\"><div class=\"accordion-body\"><p>Yes, Roshni Store delivers nationwide across Pakistan, covering all major cities, towns, and even remote locations. We partner with trusted courier services to ensure timely deliveries. No matter where you live, we bring your favorite products to your doorstep, making shopping easy and convenient for everyone.</p><p><br></p></div></div></div></div><div class=\"accordion mb-3\" id=\"accordion_1754886168948\">\r\n                            <div class=\"accordion-item\">\r\n                                <h2 class=\"accordion-header\">\r\n                                    <button class=\"accordion-button\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapse_1754886168948\" aria-expanded=\"true\">How can I track my order after making a purchase?</button>\r\n                                </h2>\r\n                                <div id=\"collapse_1754886168948\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#accordion_1754886168948\" style=\"\">\r\n                                    <div class=\"accordion-body\">\r\n                                        <p>Once your order is processed and shipped, you’ll receive a tracking ID through email or SMS. This ID lets you track your order’s real-time status online until it reaches you. Our system ensures transparency, so you always know where your package is during delivery.</p><p><br></p></div></div></div></div><div class=\"accordion mb-3\" id=\"accordion_1754886191886\">\r\n                            <div class=\"accordion-item\">\r\n                                <h2 class=\"accordion-header\">\r\n                                    <button class=\"accordion-button\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapse_1754886191886\" aria-expanded=\"true\">Are your beauty and fashion products original and authentic quality?</button>\r\n                                </h2>\r\n                                <div id=\"collapse_1754886191886\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#accordion_1754886191886\" style=\"\">\r\n                                    <div class=\"accordion-body\">\r\n                                        <p>Absolutely! We only source products from trusted suppliers and manufacturers. Every beauty, fashion, and accessory item at Roshni Store goes through a strict quality check. Our commitment is to offer 100% authentic, durable, and premium products that our customers can trust and enjoy with confidence.</p><p><br></p></div></div></div></div><div class=\"accordion mb-3\" id=\"accordion_1754886214409\">\r\n                            <div class=\"accordion-item\">\r\n                                <h2 class=\"accordion-header\">\r\n                                    <button class=\"accordion-button\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapse_1754886214409\" aria-expanded=\"true\">What payment methods does Roshni Store accept for online purchases?</button>\r\n                                </h2>\r\n                                <div id=\"collapse_1754886214409\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#accordion_1754886214409\" style=\"\">\r\n                                    <div class=\"accordion-body\">\r\n                                        <p>We offer multiple secure payment options, including cash on delivery, bank transfers, and popular digital wallet services in Pakistan. This flexibility ensures our customers can choose a payment method they are most comfortable with. All transactions are encrypted to protect your personal and financial information.</p><p><br></p></div></div></div></div><div class=\"accordion mb-3\" id=\"accordion_1754886240726\">\r\n                            <div class=\"accordion-item\">\r\n                                <h2 class=\"accordion-header\">\r\n                                    <button class=\"accordion-button\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapse_1754886240726\" aria-expanded=\"true\">How can I return or exchange an item after purchase?</button>\r\n                                </h2>\r\n                                <div id=\"collapse_1754886240726\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#accordion_1754886240726\" style=\"\">\r\n                                    <div class=\"accordion-body\">\r\n                                        <p>If you’re not satisfied with your order, you can request a return or exchange within 7 days of receiving it. Simply contact our support team, share your order details, and we’ll guide you through the process. Items must be unused, in original packaging, and eligible for return.</p><p><br></p></div></div></div></div><div class=\"accordion mb-3\" id=\"accordion_1754886258999\">\r\n                            <div class=\"accordion-item\">\r\n                                <h2 class=\"accordion-header\">\r\n                                    <button class=\"accordion-button\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapse_1754886258999\" aria-expanded=\"true\">Do you offer discounts or special promotions throughout the year?</button>\r\n                                </h2>\r\n                                <div id=\"collapse_1754886258999\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#accordion_1754886258999\" style=\"\">\r\n                                    <div class=\"accordion-body\">\r\n                                        <p>Yes! Roshni Store regularly offers discounts, flash sales, and festive promotions. We also introduce exclusive deals for our loyal customers. To never miss out, follow us on social media and subscribe to our newsletter. This way, you can grab your favorite products at unbeatable prices.</p>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div><div class=\"accordion mb-3\" id=\"accordion_1754886240726\"><div class=\"accordion-item\"><div id=\"collapse_1754886240726\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#accordion_1754886240726\" style=\"\"><div class=\"accordion-body\"><p><br></p>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div><div class=\"accordion mb-3\" id=\"accordion_1754886214409\"><div class=\"accordion-item\"><div id=\"collapse_1754886214409\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#accordion_1754886214409\" style=\"\"><div class=\"accordion-body\"><p><br></p>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div><div class=\"accordion mb-3\" id=\"accordion_1754886191886\"><div class=\"accordion-item\"><div id=\"collapse_1754886191886\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#accordion_1754886191886\" style=\"\"><div class=\"accordion-body\"><p><br></p>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div><div class=\"accordion mb-3\" id=\"accordion_1754886168948\"><div class=\"accordion-item\"><div id=\"collapse_1754886168948\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#accordion_1754886168948\" style=\"\"><div class=\"accordion-body\"><p><br></p>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div><div class=\"accordion mb-3\" id=\"accordion_1754886109052\"><div class=\"accordion-item\"><div id=\"collapse_1754886109052\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#accordion_1754886109052\" style=\"\"><div class=\"accordion-body\"><p><br></p>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div>', '2025-08-11 04:24:36', '2025-08-11 04:24:36');

