--
-- Table structure for table `products`
--

CREATE TABLE `products` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `name` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `price` decimal(8,2) NOT NULL,
  `color` varchar(255) DEFAULT NULL,
  `discount_price` decimal(8,2) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `category_id` bigint(20) UNSIGNED DEFAULT NULL,
  `sub_category_id` bigint(20) UNSIGNED DEFAULT NULL,
  `info` longtext DEFAULT NULL,
  `description` longtext DEFAULT NULL,
  `link` longtext DEFAULT NULL,
  `availability` varchar(255) NOT NULL DEFAULT 'in stock',
  `material` varchar(255) DEFAULT NULL,
  `tag_id` bigint(20) UNSIGNED DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `products`
--

INSERT INTO `products` (`id`, `name`, `slug`, `price`, `color`, `discount_price`, `created_at`, `updated_at`, `category_id`, `sub_category_id`, `info`, `description`, `link`, `availability`, `material`, `tag_id`) VALUES
(31, '1 Pc Women\'s Unstitched Swiss Lawn Printed Shirt', '1-pc-womens-unstitched-swiss-lawn-printed-shirt', '1699.00', NULL, '2199.00', '2025-08-17 19:27:01', '2025-08-18 00:50:58', 5, 5, '<div><h2 class=\"\"><span style=\"font-size: 24px;\"><b>About this item</b></span><b>:</b></h2>• Fabric: Swiss Lawn&nbsp;</div><div>• Pattern: Printed</div><div>• Shirt Front Pattern: Printed</div><div>• Daman: Printed</div><div>• Shirt Back Pattern: Plain</div><div>• Number Of Pieces: 1 Pc</div><div>• Color: Multicolor</div><div>• Package Includes: 1 x Shirt</div><div>• Shirt Cutting: 2.25 Yards&nbsp;</div><div>• Note: There might be an error of 1-3 cm due to manual measurement, and slight color differences may occur as a result of varying lighting and monitor effects.</div><div><br></div>', '<p data-start=\"93\" data-end=\"149\">✨ <strong data-start=\"95\" data-end=\"145\">Swiss Lawn Printed Shirt – Multicolor Elegance</strong> ✨</p><p data-start=\"151\" data-end=\"411\">Crafted from premium <strong data-start=\"172\" data-end=\"193\">Swiss Lawn fabric</strong>, this shirt is designed to keep you cool and stylish throughout the season. The <strong data-start=\"274\" data-end=\"323\">printed front, daman, and multicolor patterns</strong> add a touch of sophistication, while the <strong data-start=\"365\" data-end=\"379\">plain back</strong> ensures balance and elegance.</p><p data-start=\"413\" data-end=\"613\">With a comfortable <strong data-start=\"432\" data-end=\"453\">2.25-yard cutting</strong>, it’s easy to stitch into your desired style. Whether you prefer a trendy cut or a traditional look, this <strong data-start=\"560\" data-end=\"577\">1-piece shirt</strong> is perfect for versatile styling.</p><p data-start=\"615\" data-end=\"637\">🌸 <strong data-start=\"618\" data-end=\"635\">Key Features:</strong></p><p>\r\n\r\n\r\n\r\n</p><ul data-start=\"638\" data-end=\"923\">\r\n<li data-start=\"638\" data-end=\"692\">\r\n<p data-start=\"640\" data-end=\"692\">High-quality Swiss Lawn fabric – breathable &amp; soft</p>\r\n</li>\r\n<li data-start=\"693\" data-end=\"742\">\r\n<p data-start=\"695\" data-end=\"742\">Printed front &amp; daman for a chic, modern vibe</p>\r\n</li>\r\n<li data-start=\"743\" data-end=\"781\">\r\n<p data-start=\"745\" data-end=\"781\">Plain back for an elegant contrast</p>\r\n</li>\r\n<li data-start=\"782\" data-end=\"842\">\r\n<p data-start=\"784\" data-end=\"842\">Multicolor design suitable for casual &amp; semi-formal wear</p>\r\n</li>\r\n<li data-start=\"843\" data-end=\"895\">\r\n<p data-start=\"845\" data-end=\"895\">2.25-yard shirt cutting for customized stitching</p>\r\n</li>\r\n<li data-start=\"896\" data-end=\"923\">\r\n<p data-start=\"898\" data-end=\"923\">Includes: <strong data-start=\"908\" data-end=\"921\">1 x Shirt</strong></p><p data-start=\"898\" data-end=\"923\"><strong data-start=\"908\" data-end=\"921\"><br></strong></p><p data-start=\"898\" data-end=\"923\"><img src=\"data:image/jpeg;base64,\" data-filename=\"MZ117620012SHKLFS-media-1.jpg\" style=\"width: 100%;\"><strong data-start=\"908\" data-end=\"921\"><br></strong></p></li></ul>', '<p>https://www.shop.markaz.app/explore/product/1%20Pc%20Women\'s%20Unstitched%20Swiss%20Lawn%20Printed%20Shirt/400018</p>', 'in stock', NULL, NULL);
